"""Pydantic schemas for request and processing."""

from datetime import datetime
from typing import List, Optional

from pydantic import BaseModel, Field, HttpUrl


class YapPayload(BaseModel):
    """Incoming webhook payload."""

    title: str = Field(..., max_length=256)
    url: HttpUrl
    source: Optional[str] = Field(default=None, max_length=128)
    source_type: Optional[str] = Field(default="webhook", max_length=32)
    lang: Optional[str] = Field(default=None, max_length=16)
    tags: List[str] = Field(default_factory=list)


class GeneratedCopy(BaseModel):
    """Text generated by OpenAI."""

    text_ko: str
    text_en: str
    hashtags: str
    prompt_version: str
    token_usage: Optional[int] = None


class PostingResult(BaseModel):
    """Result of posting to a channel."""

    channel: str
    status: str
    detail: Optional[str] = None


class YapResponse(BaseModel):
    """Webhook response payload."""

    hash: str
    status: str
    posted_at: Optional[datetime] = None
    posts: List[PostingResult] = Field(default_factory=list)
    message: Optional[str] = None


class QueueItem(BaseModel):
    """Represents a pending post in the queue."""

    hash: str
    title: str
    status: str
    manual_review_required: bool
    approved: bool
    queued_at: Optional[datetime]
    attempt_count: int
    priority: int
    source_type: Optional[str]
    tags: List[str] = Field(default_factory=list)
